import pytest

@pytest.mark.parametrize(
    "username, expected_status",
    [
        ("user1", 200),  # Valid username
        ("nonexistentuser", 404),  # Invalid username
        ("", 400),  # Empty username
    ]
)
def test_get_user_by_name(api_client, valid_api_key, username, expected_status):
    """
    Test the GET /user/{username} endpoint for various scenarios.
    """
    headers = {
        "Authorization": f"Bearer {valid_api_key}"
    }
    endpoint = f"user/{username}"
    
    response = api_client.get(endpoint, headers=headers)
    
    assert response.status_code == expected_status, (
        f"Unexpected status code for username: {username}, "
        f"Expected: {expected_status}, Got: {response.status_code}"
    )
    
    if expected_status == 200:
        response_data = response.json()
        assert isinstance(response_data, dict), "Response body is not a JSON object"
        assert "id" in response_data, "Missing 'id' in response"
        assert "username" in response_data, "Missing 'username' in response"
        assert response_data["username"] == username, (
            f"Expected username: {username}, Got: {response_data['username']}"
        )
    elif expected_status == 400:
        assert "Invalid username supplied" in response.text, "Unexpected error message for bad request"
    elif expected_status == 404:
        assert "User not found" in response.text, "Unexpected error message for not found user"


